mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 1.5;
  vec3 q = p;
  q.z = mod(q.z, 4.0) - 2.0;
  q.x = abs(q.x) - 2.0;
  float col = length(q.xz) - (0.35 + 0.05 * sin(p.y * 4.0));
  float fl = p.y + 1.5;
  float ce = 2.0 - p.y;
  return min(col, min(fl, ce));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 50; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 18.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.0, 0.05);
  if (t < 18.0) {
    vec3 pos = ro + rd * t;
    float neon = step(0.9, sin(pos.z * 1.57 + time * 3.0));
    vec3 neonCol = mix(vec3(0.0, 0.9, 1.0), vec3(1.0, 0.1, 0.6), sin(pos.z * 0.5) * 0.5 + 0.5);
    float fog = 1.0 / (1.0 + t * t * 0.02);
    col = (vec3(0.05, 0.04, 0.08) + neon * neonCol * (1.5 + bass)) * fog;
  }
  ret = col;
}
